UPDATE mosaics SET definition = '{"id": "mental-beszed-iras", "name": "Beszéd – Írás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "Beszéltetés. A varázsló az áldozat száján át beszél: az áldozat azt mondja, amit a varázsló szeretne. Nem helyettesíti az Akaratátvitelt: az áldozat tisztában van vele, hogy nem ezt szeretné mondani, de nincs hatalma a saját beszédközpontja felett. Az egyetlen, amit tehet, hogy írásban vagy taglejtésekkel tiltakozik, esetleg mást közöl.", "source": "Part 6"}'::jsonb
WHERE id = 'mental-beszed-iras' AND definition = '{"id": "mental-beszed-iras", "name": "Beszéd – Írás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "speech, write: put in something that was not there, e.g. a memory", "source": "Part 6"}'::jsonb;
UPDATE mosaics SET definition = '{"id": "mental-beszed-zavaras", "name": "Beszéd – Zavarás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 3}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 3, "step": {"mp": 2, "e": 3}}, "cost": {"pattern": "flat", "baseMp": 2}, "inputs": [], "effect": "Dadogás. Az áldozat képtelen tisztán ejteni a szavakat, folyamatosan beszélni; dadogni fog, vagy szinte az érthetetlenségig torzítja a szavakat, akár a részeg ember. Hogy melyik hatás következik be, azt a varázsló határozza meg.", "source": "Part 6"}'::jsonb
WHERE id = 'mental-beszed-zavaras' AND definition = '{"id": "mental-beszed-zavaras", "name": "Beszéd – Zavarás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 3}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 3, "step": {"mp": 2, "e": 3}}, "cost": {"pattern": "flat", "baseMp": 2}, "inputs": [], "effect": "speech, disrupt: make it hard to focus; jumbled", "source": "Part 6"}'::jsonb;
UPDATE mosaics SET definition = '{"id": "mental-beszed-benitas", "name": "Beszéd – Bénítás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "Némaság. Az áldozat megnémul: egy szót sem tud kiejteni, csak érthetetlen nyögdécselésre képes, amíg a varázslat időtartama tart.", "source": "Part 6"}'::jsonb
WHERE id = 'mental-beszed-benitas' AND definition = '{"id": "mental-beszed-benitas", "name": "Beszéd – Bénítás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "speech, disable: remove a thought, memory, ability or feeling", "source": "Part 6"}'::jsonb;
UPDATE mosaics SET definition = '{"id": "mental-erzekeles-olvasas", "name": "Érzékelés – Olvasás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 5}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "Érzékelés. A varázsló az áldozat érzékszerveivel érzékel: látja, amit az lát, hallja, amit az hall, tapint, ízlel, szagol, mintha csak belekerült volna a másik testébe.", "source": "Part 6"}'::jsonb
WHERE id = 'mental-erzekeles-olvasas' AND definition = '{"id": "mental-erzekeles-olvasas", "name": "Érzékelés – Olvasás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 5}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "perception, read: glimpse into someone''s mind", "source": "Part 6"}'::jsonb;
UPDATE mosaics SET definition = '{"id": "mental-erzekeles-iras", "name": "Érzékelés – Írás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 2, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 2}, "inputs": [], "effect": "Illúzió. A varázsló becsapja az áldozat érzékelését: nem létező dolgokat láttat, nem hallható hangokat hallat vele, és ez igaz a többi érzékszervre is. Az áldozat úgy érezheti, mintha egészen más helyen járna, ahol más dolgok történnek vele.\n\nHa az áldozat fejében megfordul, hogy mindez nem a valóság, Intelligencia próbára jogosult. Sikeres próba esetén a téves érzékelés továbbra is tart, de az áldozat már tisztában van vele, hogy az érzékszervei nem a valóságról tájékoztatják.\n\nIllúzióval sok mindent el lehet érni, de soha nem okozhat valódi sebet, főképp nem halált.\n\nHogy az illúzió ne csak egy előre megtervezett történet legyen, hanem az áldozat cselekedetei szerint változzon (tökéletes pszeudó-valóság), a varázslónak tudnia kell, hogyan cselekszik az áldozat az érzékszerveivel a csak számára létező világban; ezt Gondolatolvasással érheti el.\n\nA pszeudó-valóság folyamatos változásához a varázslónak a varázslat végéig egyfolytában összpontosítania kell. Ez kizárja más varázslatok alkalmazását és a kézi harcot, de nem zárja ki a mozgást és a beszédet.", "source": "Part 6"}'::jsonb
WHERE id = 'mental-erzekeles-iras' AND definition = '{"id": "mental-erzekeles-iras", "name": "Érzékelés – Írás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 2, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 2}, "inputs": [], "effect": "perception, write: put in something that was not there, e.g. a memory", "source": "Part 6"}'::jsonb;
UPDATE mosaics SET definition = '{"id": "mental-erzekeles-zavaras", "name": "Érzékelés – Zavarás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 3}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "Tompítás. Az áldozat érzékszervei eltompulnak: homályosan lát, tompán hall, durván tapint, a szaglása és ízlelése is jelentősen romlik. Ügyességet és figyelmet igénylő kézimunkát nem képes végezni.\n\nTÉ, VÉ és KÉ annyival csökken, ahányszoros az erősítés; a CÉ ennek a háromszorosával, ami általában lehetetlenné teszi a célzott lövést.", "source": "Part 6"}'::jsonb
WHERE id = 'mental-erzekeles-zavaras' AND definition = '{"id": "mental-erzekeles-zavaras", "name": "Érzékelés – Zavarás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 3}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "perception, disrupt: make it hard to focus; jumbled", "source": "Part 6"}'::jsonb;
UPDATE mosaics SET definition = '{"id": "mental-erzekeles-benitas", "name": "Érzékelés – Bénítás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 2, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 2}, "inputs": [], "effect": "Érzéketlenség. Az áldozat semmit nem érzékel: vak, süket, nem szagol, nem képes ízlelni, tapintása is érzéketlen. A világ létének jelei megszűnnek számára. Aki még soha nem tapasztalt ilyet, erős sokkot kap; sikertelen Asztrál próba esetén eszméletlenné válik.\n\nA hatodik érzékre és a Pszi azonos nevű diszciplínájának hatására nincs befolyással. Az Érzékélesítés diszciplína nem szünteti meg a Mentálmágiával okozott Érzéketlenséget.", "source": "Part 6"}'::jsonb
WHERE id = 'mental-erzekeles-benitas' AND definition = '{"id": "mental-erzekeles-benitas", "name": "Érzékelés – Bénítás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 2, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 2}, "inputs": [], "effect": "perception, disable: remove a thought, memory, ability or feeling", "source": "Part 6"}'::jsonb;
UPDATE mosaics SET definition = '{"id": "mental-emlek-olvasas", "name": "Emlék – Olvasás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 5}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 2, "step": {"mp": 1, "e": 2}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "Emlékolvasás. A varázsló az áldozat emlékei között olvas. A Gondolatolvasáshoz hasonló, de múltbéli eseményeket fürkész, amelyeknek az áldozat tanúja volt. Egyidejűleg csak egyetlen meghatározott mozzanatról szerezhet tudomást, annak is csak egy időben éppolyan hosszú szakaszáról, mint amennyi az Időtartam.\n\nAz áldozat emlékezetében a mozzanat felidéződik, és az illető magában végigéli azt; a varázsló ennek a filmszerű, valós idejű vetítésnek a tanúja. Így Emlékolvasással akár több óra vagy nap eseményeiről is tudomást szerezhet, de ez az eseménnyel azonos időt igényel (meglehetős türelmet kíván).", "source": "Part 6"}'::jsonb
WHERE id = 'mental-emlek-olvasas' AND definition = '{"id": "mental-emlek-olvasas", "name": "Emlék – Olvasás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 5}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 2, "step": {"mp": 1, "e": 2}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "memory, read: glimpse into someone''s mind", "source": "Part 6"}'::jsonb;
UPDATE mosaics SET definition = '{"id": "mental-emlek-iras", "name": "Emlék – Írás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "Feledés. Két változata van, a varázsló választ:\nTörlés: az áldozat emlékeiből egyetlen momentumot töröl, annak is csak olyan hosszú szakaszát, amennyi az időtartam. A törölt emlék soha többé nem szerezhető vissza, mágikus úton sem.\nHamis emlék: az áldozat elméjébe hamis emlékképeket ültet (a fenti időbeli és témabeli megszorításokkal). Az áldozat ezt teljes mértékben a magáénak tekinti. Hamis voltára csak egy másik varázsló jöhet rá, aki az adott mozzanat felől kifürkészi Emlékolvasással, és csak akkor, ha az Emlékolvasás erősítése nagyobb vagy egyenlő a hamis emlék elhelyezésére használt varázslat erősségével.", "source": "Part 6"}'::jsonb
WHERE id = 'mental-emlek-iras' AND definition = '{"id": "mental-emlek-iras", "name": "Emlék – Írás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "memory, write: put in something that was not there, e.g. a memory", "source": "Part 6"}'::jsonb;
UPDATE mosaics SET definition = '{"id": "mental-emlek-zavaras", "name": "Emlék – Zavarás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 3}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 2, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 2}, "inputs": [], "effect": "Részleges Amnézia. Az áldozat egyáltalán nem emlékszik közeli múltjára; mindent, ami az érintett idő alatt történt vele, meg nem történtnek tekint. Hogy mennyi idő esik ki, azt a Zavarás erőssége (E) határozza meg: minden E egy napot jelent.\n\nAz időtartam elmúltával az elfeledett emlékek maradéktalanul visszatérnek, de nem egyik pillanatról a másikra, hanem órák alatt.", "source": "Part 6"}'::jsonb
WHERE id = 'mental-emlek-zavaras' AND definition = '{"id": "mental-emlek-zavaras", "name": "Emlék – Zavarás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 3}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 2, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 2}, "inputs": [], "effect": "memory, disrupt: make it hard to focus; jumbled", "source": "Part 6"}'::jsonb;
UPDATE mosaics SET definition = '{"id": "mental-emlek-benitas", "name": "Emlék – Bénítás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 3, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 3}, "inputs": [], "effect": "Teljes Amnézia. Az áldozat elfelejt minden emlékét, egész életét, még a gyermekkorára sem emlékszik. Elfelejti Kasztját, Tapasztalati Szintjét, Képzettségeit, egyszóval mindent.\n\nAz emlékközpont bénultságának elmúltával az emlékek visszatérnek, de nem egyik pillanatról a másikra, hanem órák, néha napok alatt.", "source": "Part 6"}'::jsonb
