UPDATE mosaics SET definition = '{"id": "mental-mozgas-olvasas", "name": "Mozgás – Olvasás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 5}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 2, "step": {"mp": 1, "e": 2}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "Követés. A varázsló tudomást szerez az áldozat minden mozdulatáról az Időtartam alatt: kéz-, lábmozdulat, szemmozgás, még egy mély lélegzetvétel is.", "source": "Part 6"}'::jsonb
