UPDATE mosaics SET definition = '{"id": "mental-mozgas-iras", "name": "Mozgás – Írás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 2, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 2}, "inputs": [], "effect": "Irányítás. A varázsló irányítja az áldozat mozdulatait. Ezek csak viszonylag egyszerűek lehetnek (pl. varázslás, kardforgatás nem). Ha nincs parancs valamely mozdulatra, vagy az előzőt már végrehajtotta, az áldozat a következőig maga is cselekedhet; ez nyomban félbeszakad, amint új utasítást kap.\n\nAz életösztön erősebb az Irányításnál: ha a varázsló öngyilkos cselekedetre kényszeríti az áldozatot, az újabb Mágiaellenállásra jogosult. Sikeres próba esetén az illető kitör a varázslat hatása alól; sikertelen esetén végrehajtja az öngyilkossághoz vezető mozdulatot.", "source": "Part 6"}'::jsonb
