UPDATE mosaics SET definition = '{"id": "mental-mozgas-zavaras", "name": "Mozgás – Zavarás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 3}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "Kábaság. Az áldozat kábán, erőtlenül mozog, elveszti az egyensúlyérzékét; mozdulatai kiszámíthatatlanok, akár a részeg emberé.\n\nTÉ, VÉ, KÉ annyival csökken, amennyi a varázslat erőssége (E), a CÉ ennek a duplájával. Varázsolni képtelen; ereje, gyorsasága és ügyessége az erősséggel (E) fordított arányban rohamosan csökken: minden 5 E 1 képességpont csökkenést eredményez (5 E = 1 pont, 10 E = 2 pont, 15 E = 3 pont, és így tovább).", "source": "Part 6"}'::jsonb
