UPDATE mosaics SET definition = '{"id": "mental-mozgas-benitas", "name": "Mozgás – Bénítás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 3, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 3}, "inputs": [], "effect": "Bénultság. Az áldozat az Időtartam lejártáig megbénul, mozdulni sem képes. Fegyvert forgatni, célozni, védekezni, varázsolni nem tud, de szellemi és pszi képességeinek birtokában marad.", "source": "Part 6"}'::jsonb
