UPDATE mosaics SET definition = '{"id": "mental-akarat-olvasas", "name": "Akarat – Olvasás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 5}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "effect": "Gondolatolvasás. A varázsló az áldozat gondolataiban olvas, azokban, amelyek azt éppen foglalkoztatják. Minél nagyobb az erősítés, annál mélyebb, avagy elvontabb gondolatoknak jut nyomára.\n\nKis (1–15 E) erősítés esetén ezek csak felületes gondolatok lehetnek, olyanok, amelyek az elkövetkező pillanatok cselekvéseire vonatkoznak. Komolyabb erősítés esetén már hosszabb távú, vagy elvont gondolatok és szándékok is a varázsló tudomására jutnak.", "source": "Part 6"}'::jsonb
