UPDATE mosaics SET definition = '{"id": "mental-akarat-iras", "name": "Akarat – Írás", "school": "mental", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"perc": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 4, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 4}, "inputs": [], "effect": "Akaratátvitel. A varázsló rákényszeríti akaratát az áldozatra. Az akként cselekszik, beszél, harcol, ahogyan a varázsló azt meghatározza. Teljes Tudatával hiszi, hogy azt tenni kívánja, a saját gondolata és vágya. Meg sem fordul a fejében, hogy a motiváció netán mástól származik.\n\nÖngyilkos cselekedetre kapott parancsnál Akaraterő próbát tehet. Sikeres próbánál kiszabadul a varázslat hatása alól, és tudatába kerül a befolyásoltságának; ekkor sikertelen Asztrál próba esetén vak gyűlölet ébred benne a varázsló iránt (hatása az Asztrálmágia fejezetében leírt Gyűlölet varázslathoz hasonló). Ha az Asztrál próbája sikeres, ura marad érzelmeinek (karakter esetén a játékos dönti el, miként érez a varázsló irányában).", "source": "Part 6"}'::jsonb
