UPDATE mosaics SET definition = '{"id": "mental-akarat-zavaras", "name": "Akarat – Zavarás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 3}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 3, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 3}, "inputs": [], "effect": "Zavarodottság. Az áldozat összezavarodik, nincs egy tiszta gondolata, nem képes dönteni: a legapróbb ügyekben is tanácstalan. Fejében egymást kergetik az összekeveredett gondolatok.\n\nVarázsolni képtelen; harcolni (támadni és védekezni) is csak akkor tud, ha minden egyes körben sikeres Akaraterő és Intelligencia próbát tesz.", "source": "Part 6"}'::jsonb
