UPDATE mosaics SET definition = '{"id": "mental-akarat-benitas", "name": "Akarat – Bénítás", "school": "mental", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "meditation", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 1}}}, "range": {"kind": "meters", "value": 20}, "resistance": {"kind": "school", "school": "mental"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 5, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 5}, "inputs": [], "effect": "Tudattalanság. Az áldozat elméje lebénul. Képtelen mérlegelni, gondolkodni; pusztán indulatai, érzelmei, vágyai irányítják. Az egyik pillanatban sír, a másikban kacag; elvakultan imádja barátait, társait, aztán a legapróbb sérelem után fegyverrel ront rájuk, és teljes szívéből gyűlöli őket. A varázs hatására minden Asztrálmágiával okozott érzelem vakká erősödik.", "source": "Part 6"}'::jsonb
